@extends('layouts.app') @section('title','Buat Pembelian') @section('heading','Buat Pembelian') @section('content')<div class="form-panel wide-form"><p class="muted">Pilih supplier dan satu atau lebih produk. Harga beli diambil dari data produk.</p><form method="POST" action="{{ route('purchases.store') }}">@csrf<div class="form-grid"><div><label>Supplier <span class="required">*</span></label><select name="supplier_id" required><option value="">Pilih supplier</option>@foreach($suppliers as $s)<option value="{{ $s->id }}" @selected(old('supplier_id')==$s->id)>{{ $s->name }}</option>@endforeach</select></div><div><label>Tanggal Pembelian <span class="required">*</span></label><input type="datetime-local" name="purchased_at" value="{{ old('purchased_at',now()->format('Y-m-d\TH:i')) }}" required></div></div><div class="section-heading"><h3>Item Pembelian</h3><button type="button" class="btn secondary small" onclick="addRow('purchase-items')">＋ Tambah Item</button></div><div id="purchase-items" class="item-list"><div class="item-row"><select name="items[0][product_id]" required><option value="">Pilih produk</option>@foreach($products as $p)<option value="{{ $p->id }}">{{ $p->sku }} — {{ $p->name }} (harga beli Rp {{ number_format($p->purchase_price,0,',','.') }})</option>@endforeach</select><input type="number" name="items[0][quantity]" min="1" value="1" required placeholder="Kuantitas"><button type="button" class="btn small danger-btn" onclick="removeRow(this)">Hapus</button></div></div><div class="form-actions"><a class="btn ghost" href="{{ route('purchases.index') }}">Batal</a><button class="btn primary">Simpan Pembelian</button></div></form></div><script>let itemIndex=1;function addRow(id){const box=document.getElementById(id);const first=box.querySelector('.item-row');const row=first.cloneNode(true);row.querySelectorAll('select,input').forEach(el=>{el.name=el.name.replace(/items\[\d+\]/,'items['+itemIndex+']');if(el.tagName==='SELECT')el.selectedIndex=0;else el.value=1;});box.appendChild(row);itemIndex++;}function removeRow(btn){const box=btn.closest('.item-list');if(box.children.length>1)btn.closest('.item-row').remove();}</script>@endsection
